  \node[below left] at (D) {$D$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 1: Hình bình hành $ABCD$}
\end{minipage}

\begin{minipage}[t]{0.58\linewidth}\vspace{0pt}
\textbf{Ví dụ mẫu 1.} Xét hình bình hành $ABCD$. Gọi $E, F$ lần lượt là trung điểm của $AB$ và $CD$. Chứng minh tứ giác $AECF$ là hình bình hành. [[br]]
\textit{Lời giải}: [[br]]
Vì $ABCD$ là HBH nên $AB \parallel CD$ và $AB = CD$. [[br]]
Vì $E$ là trung điểm $AB \Rightarrow AE = \dfrac{1}{2}AB$. [[br]]
Vì $F$ là trung điểm $CD \Rightarrow CF = \dfrac{1}{2}CD$. [[br]]
Suy ra $AE = CF$. Mặt khác $E \in AB, F \in CD \Rightarrow AE \parallel CF$. [[br]]
Tứ giác $AECF$ có $AE \parallel CF$ và $AE = CF \Rightarrow AECF$ là hình bình hành (Dấu hiệu 3 SGK).
\end{minipage}\hfill
